package cn.huankan.collector;
import java.nio.charset.StandardCharsets;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class PracticalParsersTest {
 @Test void fedCalendarUsesExplicitMonthAndListedDaysOnly(){String html="<div class=\"row-title text-center\"><h4>October 2026</h4></div><div class=\"col-xs-7\"><p>H.15 - Selected Interest Rates</p></div><div class=\"col-xs-3\"><p>1, 2, 5</p></div>";var rows=OfficialCalendarParser.parse("FED",html);assertEquals(3,rows.size());assertEquals("2026-10-05",rows.getLast().date().toString());assertEquals(0,OfficialCalendarParser.parse("FED",html.replace("October 2026","Month unknown")).size());}
 byte[] bytes(String s){return s.getBytes(StandardCharsets.UTF_8);}
 String series="series_id\titem_code\tseasonal\tperiodicity_code\tbase_period\nCUUR0000SA0\tSA0\tU\tR\t1982-84=100\n";
 String notes="footnote_code\tfootnote_text\nP\tPreliminary\n";
 @Test void bulkSeriesAndDataPreserveValueNotesAndMonth(){var r=BlsFileAdapter.parse(bytes(series),bytes("series_id\tyear\tperiod\tvalue\tfootnote_codes\nCUUR0000SA0\t2026\tM01\t310.25\tP\nCUUR0000SA0\t2026\tM13\t312\t\n"),bytes(notes),2026,2026);assertEquals(1,r.size());assertEquals("310.25",r.getFirst().value().toPlainString());assertEquals("Preliminary",r.getFirst().footnotes().getFirst().get("text"));assertEquals("2026-01-01",r.getFirst().date().toString());}
 @Test void bulkCannotGuessBaseUnit(){assertThrows(IllegalArgumentException.class,()->BlsFileAdapter.parse(bytes(series.replace("1982-84=100","UNKNOWN")),bytes("unused"),bytes(notes),2026,2026));}
 @Test void unknownFootnotesAndDuplicatePeriodsAreRejected(){String row="CUUR0000SA0\t2026\tM01\t310.25\tX\n",header="series_id\tyear\tperiod\tvalue\tfootnote_codes\n";assertThrows(IllegalArgumentException.class,()->BlsFileAdapter.parse(bytes(series),bytes(header+row),bytes(notes),2026,2026));assertThrows(IllegalArgumentException.class,()->BlsFileAdapter.parse(bytes(series),bytes(header+row.replace("X","P").repeat(2)),bytes(notes),2026,2026));}
 @Test void calendarUsesOnlyExplicitOfficialDates(){var r=OfficialCalendarParser.parse("ECB","<dt>29/10/2026</dt><dd>Press conference following the Governing Council meeting</dd>");assertEquals(1,r.size());assertEquals("2026-10-29",r.getFirst().date().toString());assertEquals(0,OfficialCalendarParser.parse("ECB","Meeting every six weeks").size());assertEquals(0,OfficialCalendarParser.parse("FED","No explicit supported layout").size());}
 @Test void xbrlDoesNotTurnDurationIntoInstantOrChangeUnits(){String raw="{\"cik\":1,\"facts\":{\"us-gaap\":{\"Assets\":{\"units\":{\"USD\":[{\"end\":\"2025-12-31\",\"val\":123.40,\"accn\":\"0000000001-26-000001\",\"form\":\"10-K\",\"filed\":\"2026-02-01\",\"fp\":\"FY\"}]}}}}}";var facts=SecXbrlParser.parse(bytes(raw),Set.of("Assets"));assertNull(facts.getFirst().start());assertEquals("0000000001",facts.getFirst().cik());assertEquals(0,new java.math.BigDecimal("123.40").compareTo(facts.getFirst().value()));assertEquals(0,SecXbrlParser.difference(facts.getFirst(),facts.getFirst()).signum());assertThrows(IllegalArgumentException.class,()->SecXbrlParser.parse(bytes(raw.replace("USD","UNKNOWN")),Set.of("Assets")));}
}
